def _source_int(payload):
    if len(payload) in (1,2):return int.from_bytes(payload,'little',signed=True)
    return int.from_bytes((bytes(payload[:4])+bytes(4))[:4],'little',signed=True)

def _convert(value,kind):
    if kind=='masked3-equals2':return value&3==2
    if kind=='int-div1000000-to-double':return float((abs(value)//1000000)*(-1 if value<0 else 1))
    if kind in ('float32-div10','float32-div100'):
        f=lambda n:struct.unpack('<f',struct.pack('<f',n))[0]
        return f(f(value)/int(kind.split('div')[1]))
    return value

def peripheral_notification(message):
    flags=message.get('flags');body=message.get('payload')
    if (message.get('sender')!=4 or message.get('receiver')!=2 or message.get('commandSet')!=4 or message.get('commandId')!=102 or type(flags) is not int or not 0<=flags<=255 or flags&0x87 or not isinstance(body,(bytes,bytearray)) or not body):return None
    result=dict(kind='peripheral',profile=APP_PROFILE,commandId=102,timestamp=time.time()*1000,bodyHex=body.hex(),rawFlag=body[0],sourceRecordBranchSelected=body[0]==1,records=[],deviceVerified=False,modelLayoutVerified=False,referenceFrameVerified=False,physicalCompletionVerified=False)
    if body[0]!=1:return result
    offset=1
    while offset<len(body):
        if len(body)-offset<2:return None
        tag,length=body[offset:offset+2];end=offset+2+length
        if length>=128 or end>len(body):return None
        p=body[offset+2:end];signed=tag if tag<128 else tag-256
        types=[r['name'] for r in CATALOG['types'] if r['sourceId']==signed];getters=[r for r in CATALOG['getters'] if r['sourceId']==signed];value=_source_int(p) if getters else None
        views=[dict(sourceType=r['sourceType'],sourceGetter=r['sourceGetter'],conversion=r['conversion'],value=_convert(value,r['conversion'])) for r in getters]
        result['records'].append(dict(rawTag=tag,sourceSignedTag=signed,length=length,payloadHex=p.hex(),sourceTypes=types,ambiguous=len(types)>1,sourceInt32=value,sourceViews=views));offset=end
    return result
